def build(path=ROOT/'data'/'monthly_returns_pct.csv'):
    path.parent.mkdir(exist_ok=True)
    with path.open('w',encoding='utf-8',newline='') as f:
        writer=csv.writer(f,lineterminator='\n');writer.writerow(['MonthEnd',*TICKERS])
        for y in range(2021,2027):
            months=range(11,13) if y==2021 else range(1,11) if y==2026 else range(1,13)
            for i,m in enumerate(months):
                writer.writerow([f'{y}-{m:02d}-{calendar.monthrange(y,m)[1]:02d}',*[f'{VALUES[t][y][i]:.2f}' for t in TICKERS]])
    return hashlib.sha256(path.read_bytes()).hexdigest()
if __name__=='__main__': print('Frozen monthly total-return percent CSV SHA256:',build())
